    /// </summary>
    public static class ChatJsonConverter
    {
        // JSON schema classes
        private class RawLog
        {
            [JsonPropertyName("title")]
            public string Title { get; set; } = "";

            [JsonPropertyName("create_time")]
            public double CreateTime { get; set; }

            [JsonPropertyName("mapping")]
